const PAGE = 20;

export function Inbox() {
  const [mail, setMail] = useState<Mail[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`/api/mail?limit=${PAGE}`)
      .then((r) => r.json())
      .then((d) => {
        setLoading(false);
        setMail(d.items);
      })
      .catch((e) => {
        setLoading(false);
        toast.error(e.message);
      });
  }, []);

  return (
    <section>
      <h3>Inbox · {mail.length} messages</h3>
      <p className="hint">Showing up to {PAGE} messages.</p>
      {loading ? <Spinner /> : mail.length ? <List items={mail} /> : <Empty text="Oops! Nothing here yet 🙂" />}
    </section>
  );
}
